from io import BytesIO
from functools import lru_cache
import base64
from PIL import Image, ImageOps, ImageEnhance

W, H = 1200, 675

# Compact local visual atlas generated specifically for Sovpali.
# 3 columns x 2 rows: welcome, birth, priority / city, goal, photo.
_SPRITE_B64 = """[... ELLIPSIZATION ...]"""

_THEME_CELL = {
    'welcome': 0, 'gender': 0, 'birth': 1, 'place': 3, 'city': 3,
    'goal': 4, 'priority': 2, 'photo': 5, 'matching': 4,
    'profile': 5, 'pairs': 0, 'chats': 0, 'more': 2,
}


def _sprite():
    return Image.open(BytesIO(base64.b64decode(_SPRITE_B64))).convert('RGB')


def _cell(index: int, theme: str) -> bytes:
    im = _sprite()
    cw, ch = im.width // 3, im.height // 2
    row, col = divmod(index, 3)
    cell = im.crop((col * cw, row * ch, (col + 1) * cw, (row + 1) * ch))

    # Reuse the city scene for birthplace, but remove its "А где ты сейчас?"
    # speech bubble so it never contradicts the onboarding question.
    if theme == 'place':
        cell = cell.crop((0, int(cell.height * 0.28), cell.width, cell.height))

    cell = ImageOps.fit(cell, (W, H), method=Image.Resampling.LANCZOS, centering=(0.5, 0.52))
    cell = ImageEnhance.Color(cell).enhance(1.04)
    cell = ImageEnhance.Contrast(cell).enhance(1.02)
    out = BytesIO()
    cell.save(out, 'JPEG', quality=88, optimize=True, progressive=True)
    return out.getvalue()


@lru_cache(maxsize=32)
def visual(theme: str) -> bytes:
    return _cell(_THEME_CELL.get(theme, 0), theme)


def animation(theme: str = 'welcome') -> bytes:
    return visual(theme)


def as_file(data: bytes, name: str):
    bio = BytesIO(data)
    bio.name = name.rsplit('.', 1)[0] + '.jpg'
    return bio
